+      Validate_Scalar_Destination (Self, Destination, True);
+      Raise_On_Error
+        (OpenCV.Internal.C_API.Mat_Compare_Scalar_Into
+           (Self.Handle,
+            Interfaces.C.double (Value),
+            To_C_Comparison_Kind (Kind),
+            Destination.Handle),
+         "Mat scalar comparison");
+   end Compare;

